// Repository roles as the adapter records them from the permission endpoint.
export const role = (name) => ({ role: name });

export function bodyRevision(
  issue,
  lastEditedAt = null,
  kind = "implementation ticket",
) {
  return revision({
    kind,
    source: {
      type: "issue-body",
      id: issue.node_id ?? "ISSUE_42",
      editedAt: lastEditedAt,
    },
    body: issue.body,
  });
}

export function briefRevision(comment, kind = "triaged Agent Brief") {
  return revision({
    kind,
    source: {
      type: "comment",
      id: String(comment.node_id ?? comment.id),
      editedAt: comment.updated_at ?? null,
    },
    body: comment.body,
  });
}

export function revision(contract) {
  const value = JSON.stringify({
    format: "repo-canon/issue-contract-revision/v1",
    ...contract,
  });
  return `sha256:${createHash("sha256").update(value).digest("hex")}`;
}

export function feedbackState({
  status,
  revision: contractRevision,
  label = null,
  reviewer = null,
  reviewEventId = "101",
  observedEventId = null,
  sourceInvalidation = null,
  kind = "implementation ticket",
}) {
  const state = JSON.stringify(
    status === "approved"
      ? {
          status,
          revision: contractRevision,
          label,
          reviewer,
          reviewEventId,
          sourceInvalidation,
        }
      : {
          status,
          revision: contractRevision,
          label,
          reviewer,
          observedEventId,
          sourceInvalidation,
        },
  );
  if (status === "approved") {
    return `<!-- repo-canon:issue-contract-feedback -->\n<!-- repo-canon:issue-contract-state ${state} -->\n## Issue contract readiness recorded\n\nThe ${kind} at revision \`${contractRevision}\` was reviewed by @${reviewer}, whose repository role authorizes triage, and is bound to \`${label}\`. Editing or replacing the contract or removing readiness invalidates this association.`;
  }
  return `<!-- repo-canon:issue-contract-feedback -->\n<!-- repo-canon:issue-contract-state ${state} -->\n## Issue contract awaiting review\n\nThe ${kind} has the required structure at revision \`${contractRevision}\`.\n\nA fresh authorized review is required. A repository admin, maintainer, or explicitly authorized triage-role collaborator must review this exact revision, then apply one readiness label. For an Agent Brief, wait for this revision notice before applying the label. Structural validation never grants readiness.`;
}

// The maintained feedback comment, recording an approval of the direct ticket
// body by `maintainer` unless the state says otherwise.
export function approvedTicketFeedback(issue, state = {}) {
  return {
    id: 13,
    body: feedbackState({
      status: "approved",
      revision: bodyRevision(issue),
      label: "ready-for-agent",
      reviewer: "maintainer",
      ...state,
    }),
    user: bot,
  };
}

export function awaitingTicketFeedback(issue, state = {}) {
  return {
    id: 13,
    body: feedbackState({
      status: "awaiting-review",
      revision: bodyRevision(issue),
      ...state,
    }),
    user: bot,
  };
}

export const labeledBy = (login, label = "ready-for-agent", issue = {}) => ({
  action: "labeled",
  issue: { number: 42, body: issue.body, updated_at: issue.updated_at },
  label: { name: label },
  sender: { login },
});

// The readiness label event of an issue created at 17:00:00 with that label by
// `maintainer`, recorded as issue event 101 in the creation second.
export const creationTime = "2026-09-14T17:00:00Z";
export const creationLabel = (overrides = {}) => ({
  id: 101,
  event: "labeled",
  label: { name: "ready-for-agent" },
  actor: { login: "maintainer" },
  created_at: creationTime,
  ...overrides,
});

// An unedited direct ticket that `opener` created with `labels`, seen by the
// `opened` run or by the `labeled` run in which `labeler` applied `trigger`.
// `currentLabels` are the labels the run re-fetches, when an earlier run
// changed them.
export function createdWithReadiness({
  run,
  opener = "maintainer",
  labeler = opener,
  labels = ["ready-for-agent"],
  currentLabels = labels,
  trigger = "ready-for-agent",
  comments = [],
  issueEvents = [creationLabel()],
  permissions = { [opener]: role("admin") },
  bodyLastEditedAt = null,
}) {
  const issue = {
    number: 42,
    node_id: "ISSUE_42",
    body: ticketBody,
    labels: currentLabels.map((name) => ({ name })),
    state: "open",
    user: { login: opener },
    created_at: creationTime,
    updated_at: creationTime,
  };
  const createdLabels = labels.map((name) => ({ name }));
  const event =
    run === "opened"
      ? {
          action: "opened",
          issue: {
            number: 42,
            body: issue.body,
            labels: createdLabels,
            created_at: creationTime,
            updated_at: creationTime,
          },
          sender: { login: opener },
        }
      : labeledBy(labeler, trigger, issue);
  return { issue, comments, issueEvents, event, permissions, bodyLastEditedAt };
}

// The maintainer's application of readiness, event 201, that a run rejected,
// writing an awaiting-review notice that observed it; the bot's removal; and
// the maintainer's reapplication, event 203, after that notice.
const rejectedApplication = creationLabel({
  id: 201,
  created_at: "2026-09-14T17:01:00Z",
});
export const readinessRetryEvents = [
  rejectedApplication,
  { ...rejectedApplication, id: 202, event: "unlabeled", actor: bot },
  { ...rejectedApplication, id: 203, created_at: "2026-09-14T17:01:10Z" },
];

// Alice, whose `write` role cannot grant readiness, applied it as event 100,
// which a run rejected, writing a notice that observed it. The bot removed it
// (101), Bob reapplied it (203), Carol removed it (204), and Alice reapplied it
// (205). A lagging read ends at Bob's 203.
const aliceApplication = creationLabel({
  id: 100,
  actor: { login: "alice" },
});
export const reapplicationEvents = [
  aliceApplication,
  {
    ...aliceApplication,
    id: 101,
    event: "unlabeled",
    actor: bot,
    created_at: "2026-09-14T17:00:05Z",
  },
  {
    ...aliceApplication,
    id: 203,
    actor: { login: "bob" },
    created_at: "2026-09-14T17:01:00Z",
  },
  {
    ...aliceApplication,
    id: 204,
    event: "unlabeled",
    actor: { login: "carol" },
    created_at: "2026-09-14T17:01:30Z",
  },
  { ...aliceApplication, id: 205, created_at: "2026-09-14T17:01:40Z" },
];
export const laggingReapplicationEvents = reapplicationEvents.slice(0, 3);

// The labeled run of `sender`, Alice unless stated, while `ready-for-agent` is
// present, with the notice that observed 100 or, when `approved`, Bob's
// recorded approval of 203.
export function reapplicationRun({ approved = false, sender = "alice" } = {}) {
  const issue = {
    number: 42,
    node_id: "ISSUE_42",
    body: ticketBody,
    labels: [{ name: "ready-for-agent" }],
    state: "open",
    user: { login: "author" },
    created_at: "2026-09-14T16:00:00Z",
    updated_at: "2026-09-14T17:01:40Z",
  };
  const feedback = approved
    ? {
        ...approvedTicketFeedback(issue, {
          reviewer: "bob",
          reviewEventId: "203",
        }),
        updated_at: "2026-09-14T17:01:05Z",
      }
    : {
        ...awaitingTicketFeedback(issue, { observedEventId: "100" }),
        updated_at: "2026-09-14T17:00:30Z",
      };
  return {
    issue,
    comments: [feedback],
    event: labeledBy(sender, "ready-for-agent", issue),
    permissions: {
      alice: role("write"),
      bob: role("admin"),
      carol: role("admin"),
    },
  };
}

export const readinessReview = {
  id: 101,
  event: "labeled",
  label: { name: "ready-for-agent" },
  actor: { login: "maintainer" },
  created_at: "2026-09-14T17:00:00Z",
};

// The issue-contract state a feedback comment records in its marker.
export function recordedState(body) {
  const encoded = body.match(
    /<!-- repo-canon:issue-contract-state (\{.*\}) -->/,
  )?.[1];
  return encoded ? JSON.parse(encoded) : null;
}
